fn one_off(a: Str, b: Str) -> Bool {
  let ca = a.chars()
  let cb = b.chars()
  if ca.len() != cb.len() {
    return false
  }
  var diff = 0
  for i in range(0, ca.len()) {
    if ca.get_or(i, "") != cb.get_or(i, "") {
      diff = diff + 1
    }
  }
  return diff == 1
}

pub fn ladder(start: Str, goal: Str, words: List[Str]) -> Int {
  if start == goal {
    return 1
  }
  let nodes = [start].concat(words.unique())
  let n = nodes.len()
  var dist: List[Int] = []
  for _i in range(0, n) {
    dist = dist.push(-1)
  }
  dist = dist.set(0, 1)
  var queue: List[Int] = [0]
  var qh = 0
  while qh < queue.len() {
    let u = queue.get_or(qh, 0)
    qh = qh + 1
    let un = nodes.get_or(u, "")
    for v in range(0, n) {
      if dist.get_or(v, -1) < 0 and one_off(un, nodes.get_or(v, "")) {
        dist = dist.set(v, dist.get_or(u, 0) + 1)
        queue = queue.push(v)
        if nodes.get_or(v, "") == goal {
          return dist.get_or(v, 0)
        }
      }
    }
  }
  return 0
}
